const remisiones = $("Start").all();

if (remisiones.length === 0) {
  throw new Error("No llegaron artículos desde el workflow principal.");
}

const templateItem = $input.first();

if (!templateItem?.binary) {
  throw new Error("No llegó el template HI en binario. Revisa el nodo 'Leer template HI'.");
}

const binaryField = Object.keys(templateItem.binary || {})[0] || "data";
const templateBuffer = await this.helpers.getBinaryDataBuffer(0, binaryField);

let html = templateBuffer.toString("utf8");

function cleanText(value) {
  return String(value ?? "")
    .replace(/\t/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function nl2br(value) {
  return escapeHtml(value).replace(/\r?\n/g, "<br>");
}

function safeFileText(value) {
  return cleanText(value)
    .replace(/[<>:"/\\|?*]+/g, "_")
    .replace(/\s+/g, "_");
}

function toFileUri(windowsPath) {
  const normalized = cleanText(windowsPath).replace(/\\/g, "/");
  return encodeURI("file:///" + normalized.replace(/^\/+/, ""));
}

function parseFlexibleNumber(value) {
  const text = String(value ?? "").trim();

  if (!text) return NaN;

  if (text.includes(",") && text.includes(".")) {
    const lastComma = text.lastIndexOf(",");
    const lastDot = text.lastIndexOf(".");

    if (lastComma > lastDot) {
      return Number(text.replace(/\./g, "").replace(",", "."));
    }

    return Number(text.replace(/,/g, ""));
  }

  if (text.includes(",")) {
    return Number(text.replace(",", "."));
  }

  return Number(text);
}

function formatNumber(value) {
  const number = parseFlexibleNumber(value);

  if (!Number.isFinite(number)) {
    return cleanText(value);
  }

  if (Number.isInteger(number)) {
    return String(number);
  }

  return String(number).replace(/\.?0+$/, "");
}

function pluralUnit(numberText, singular, plural) {
  const number = parseFlexibleNumber(numberText);
  return number === 1 ? singular : plural;
}

function humanizeQty(value) {
  const text = cleanText(value);

  if (!text) return "";

  const match = text.match(/^([\d.,]+)\s*(.*)$/i);

  if (!match) return text;

  const number = formatNumber(match[1]);
  const unit = cleanText(match[2]).toLowerCase();

  if (["bag", "bags", "bolsa", "bolsas"].includes(unit)) {
    return `${number} ${pluralUnit(number, "Bolsa", "Bolsas")}`;
  }

  if (["roll", "rolls", "rollo", "rollos"].includes(unit)) {
    return `${number} ${pluralUnit(number, "Rollo", "Rollos")}`;
  }

  if (["pack", "packs", "paquete", "paquetes"].includes(unit)) {
    return `${number} ${pluralUnit(number, "Paquete", "Paquetes")}`;
  }

  if (["kg", "kgs", "kilo", "kilos"].includes(unit)) {
    return `${number} Kg`;
  }

  return `${number} ${cleanText(match[2])}`.trim();
}

function quantityFromCantidadExcel(value) {
  const text = cleanText(value);

  if (!text) return "";

  let match = text.match(/([\d.,]+)\s*bolsas?.*?=\s*([\d.,]+)\s*(rollos?|rolls?)/i);
  if (match) {
    return `${formatNumber(match[1])} ${pluralUnit(match[1], "Bolsa", "Bolsas")} (${formatNumber(match[2])} ${pluralUnit(match[2], "Rollo", "Rollos")})`;
  }

  match = text.match(/([\d.,]+)\s*bolsas?.*?=\s*([\d.,]+)\s*(paquetes?|packs?)/i);
  if (match) {
    return `${formatNumber(match[1])} ${pluralUnit(match[1], "Bolsa", "Bolsas")} (${formatNumber(match[2])} ${pluralUnit(match[2], "Paquete", "Paquetes")})`;
  }

  match = text.match(/([\d.,]+)\s*(rollos?|rolls?).*?=\s*([\d.,]+)\s*(kg|kgs|kilo|kilos)/i);
  if (match) {
    return `${formatNumber(match[1])} ${pluralUnit(match[1], "Rollo", "Rollos")} (${formatNumber(match[3])} Kg)`;
  }

  return text.replace(/\s*=\s*/g, " (") + (text.includes("=") ? ")" : "");
}

function getDescripcionHI(json) {
  const item = Array.isArray(json.items) ? json.items[0] : {};

  const descripcionCatalogo =
    cleanText(json.descripcion_catalogo) ||
    cleanText(item.descripcion_catalogo);

  if (descripcionCatalogo) {
    return descripcionCatalogo;
  }

  let descripcion =
    cleanText(item.descripcion) ||
    cleanText(json.descripcion);

  descripcion = descripcion
    .replace(/\s*\([^)]*\)\s*/g, " ")
    .replace(/\s*Se entregan\s+.*$/i, "")
    .replace(/\s+/g, " ")
    .trim();

  return descripcion;
}

function getCantidadHI(json) {
  const item = Array.isArray(json.items) ? json.items[0] : {};

  const cantidadExcel =
    cleanText(json.cantidad_excel) ||
    cleanText(item.cantidad_excel);

  const desdeExcel = quantityFromCantidadExcel(cantidadExcel);
  if (desdeExcel) return desdeExcel;

  const numberOfBags =
    cleanText(json.number_of_bags) ||
    cleanText(item.number_of_bags);

  const totalQty =
    cleanText(json.total_qty) ||
    cleanText(item.total_qty);

  if (numberOfBags && totalQty) {
    return `${humanizeQty(numberOfBags)} (${humanizeQty(totalQty)})`;
  }

  const qtyPerPackaging =
    cleanText(json.qty_per_packaging) ||
    cleanText(item.qty_per_packaging);

  if (totalQty && qtyPerPackaging) {
    return `${humanizeQty(totalQty)} (${humanizeQty(qtyPerPackaging)})`;
  }

  return humanizeQty(totalQty || cantidadExcel);
}

function getFechaDocumentoForFile(first) {
  const fechaDocumento = cleanText(first.fecha_documento);

  const meses = {
    enero: "01",
    febrero: "02",
    marzo: "03",
    abril: "04",
    mayo: "05",
    junio: "06",
    julio: "07",
    agosto: "08",
    septiembre: "09",
    setiembre: "09",
    octubre: "10",
    noviembre: "11",
    diciembre: "12"
  };

  // Ejemplo: "14 de Julio de 2026" → 20260714
  const fechaNormalizada = fechaDocumento
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

  const matchFechaTexto = fechaNormalizada.match(
    /(\d{1,2})\s+de\s+([a-z]+)\s+de\s+(\d{4})/i
  );

  if (matchFechaTexto) {
    const day = String(matchFechaTexto[1]).padStart(2, "0");
    const month = meses[matchFechaTexto[2]] || "00";
    const year = matchFechaTexto[3];

    return `${year}${month}${day}`;
  }

  // Respaldo: tomar fecha del nombre del archivo.
  // Ejemplo: PROGRAMACION DE ENTREGA AUDI 260714 → 20260714
  const source = cleanText(
    first.source_base_name ||
    first.file_name ||
    first.run_name ||
    ""
  );

  const matchAudiDate = source.match(/AUDI[_\s-]*(\d{6})/i);

  if (matchAudiDate) {
    const value = matchAudiDate[1]; // 260714
    const year = `20${value.slice(0, 2)}`;
    const month = value.slice(2, 4);
    const day = value.slice(4, 6);

    return `${year}${month}${day}`;
  }

  // Otro respaldo: timestamp de ejecución, ejemplo 20260715_103712
  const timestamp = cleanText(first.timestamp);

  if (/^\d{8}/.test(timestamp)) {
    return timestamp.slice(0, 8);
  }

  // Último respaldo: fecha actual
  const now = new Date();

  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, "0");
  const dd = String(now.getDate()).padStart(2, "0");

  return `${yyyy}${mm}${dd}`;
}

const first = remisiones[0].json;

const templatesDir = first.templates_dir;
const logoUri = toFileUri(`${templatesDir}\\images\\DC_logo.jpg`);

const hiTempDir =
  cleanText(first.temp_hojas_identificacion_dir) ||
  `${first.base_herramienta}\\06_ARCHIVOS TEMPORALES\\html_hojas_identificacion`;

const hojasIdentificacionDir =
  cleanText(first.hojas_identificacion_dir) ||
  `${first.base_herramienta}\\02_SALIDAS\\HOJAS_IDENTIFICACION`;

const numeroHojas = remisiones.length;
const fechaArchivo = getFechaDocumentoForFile(first);

const htmlName = `Hojas Identificacion Audi T N${numeroHojas} ${fechaArchivo}.html`;
const htmlPath = `${hiTempDir}\\${htmlName}`;

const pages = remisiones.map((item, index) => {
  const json = item.json;

  const descripcion = getDescripcionHI(json);
  const cantidad = getCantidadHI(json);

  if (!descripcion) {
    throw new Error(`Falta descripción para hoja de identificación en artículo ${index + 1}.`);
  }

  if (!cantidad) {
    throw new Error(`Falta cantidad para hoja de identificación en artículo ${index + 1}.`);
  }

  return `
    <div class="page">
      <img class="logo" src="${logoUri}" alt="Daubert México" />

      <div class="content">
        <div class="description">${nl2br(descripcion)}</div>
        <div class="quantity">${nl2br(cantidad)}</div>
      </div>
    </div>
  `;
}).join("\n");

html = html
  .replace(/<!--\s*{{hi_pages}}\s*-->/g, pages)
  .replace(/{{hi_pages}}/g, pages);

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(html, "utf8"),
  htmlName,
  "text/html"
);

return [
  {
    json: {
      ...first,

      hi_html_name: htmlName,
      hi_html_path: htmlPath,
      hi_temp_dir: hiTempDir,

      hojas_identificacion_dir: hojasIdentificacionDir,

      hi_pdf_name: htmlName.replace(/\.html?$/i, ".pdf"),
      hi_pdf_path: `${hojasIdentificacionDir}\\${htmlName.replace(/\.html?$/i, ".pdf")}`,

      logo_uri: logoUri,

      hojas_identificacion_generadas: remisiones.length,
      hi_fecha_archivo: fechaArchivo,

      pdf_script_path: first.pdf_script_path,
      clean_script_path: first.clean_script_path
    },
    binary: {
      data: binaryData
    }
  }
];

